/**
 *  For most streams with GeometrySourceType==WorldGraphGeometry, edge_path will
 *  be empty and start_stream_id will be unset.
 *
 *  If edge_path is empty and start_stream_id is unset we just query for nodes
 *  whose stream predicate matches this stream's streamId in order to fetch the stream's geometry.
 *
 *  If edge_path is non-empty and start_stream_id is set: Start at nodes with
 *  streamId=start_stream_id and follow the edge_path. Retrieve geometry from
 *  the last node on that path.
 *
 *  If edge_path is non-empty and start_stream_id is unset: Start at nodes with
 *  streamId=id of this stream and follow the edge_path to retrieve the geeometry.
 *
 *  If edge_path is empty and start_stream_id is set: Just query for nodes with
 *  streamId == start_stream_id.
 */
export class WorldGraphGeometry {
/**
 *  Edges to follow to reach the nodes with geometry.
 */
  private _edgePath!: number[];

/**
 *  Stream id of the starting node in the query path for the geometry
 */
  private _startStreamId!: ObjectId | null;

  constructor(arg?: FbsWorldGraphGeometry | Uint8Array) {
    if (arg instanceof Uint8Array) {
      const buf = new flatbuffers.ByteBuffer(arg);
      const fbs = FbsWorldGraphGeometry.getSizePrefixedRootAsWorldGraphGeometry(buf);
      this._initFromFbs(fbs);
    } else if (arg instanceof FbsWorldGraphGeometry) {
      this._initFromFbs(arg);
    } else {
      this._edgePath = [];
      this._startStreamId = null;
    }
  }

  private _initFromFbs(fbs: FbsWorldGraphGeometry): void {
    this._edgePath = Array.from({ length: fbs.edgePathLength() }, (_, i) => fbs.edgePath(i)!);
    const startStreamIdVal = fbs.startStreamId();
    this._startStreamId = startStreamIdVal ? new ObjectId(startStreamIdVal) : null;
  }

  get edgePath(): number[] {
    return this._edgePath;
  }

  set edgePath(value: number[]) {
    this._edgePath = value;
  }

  get startStreamId(): ObjectId | null {
    return this._startStreamId;
  }

  set startStreamId(value: ObjectId | null) {
    this._startStreamId = value;
  }

  toFbsT(): FbsWorldGraphGeometryT {
    const t = new FbsWorldGraphGeometryT();
    t.edgePath = this._edgePath;
    t.startStreamId = this._startStreamId ? this._startStreamId.toFbsT() : null;
    return t;
  }

  toBytes(): Uint8Array {
    const builder = new flatbuffers.Builder();
    const offset = this.toFbsT().pack(builder);
    builder.finishSizePrefixed(offset);
    return builder.asUint8Array();
  }
}

