export class GeometryData {
  private _data!: GeometryDataUnion | null;

  constructor(arg?: FbsGeometryData | Uint8Array) {
    if (arg instanceof Uint8Array) {
      const buf = new flatbuffers.ByteBuffer(arg);
      const fbs = FbsGeometryData.getSizePrefixedRootAsGeometryData(buf);
      this._initFromFbs(fbs);
    } else if (arg instanceof FbsGeometryData) {
      this._initFromFbs(arg);
    } else {
      this._data = null;
    }
  }

  private _initFromFbs(fbs: FbsGeometryData): void {
    const dataTy = fbs.dataType();
    if (dataTy === FbsGeometryDataUnion.RawGeom) {
      const dataFbsVal = fbs.data(new FbsRawGeom());
      this._data = dataFbsVal ? new RawGeom(dataFbsVal) : null;
    } else if (dataTy === FbsGeometryDataUnion.NodeIdPair) {
      const dataFbsVal = fbs.data(new FbsNodeIdPair());
      this._data = dataFbsVal ? new NodeIdPair(dataFbsVal) : null;
    } else {
      this._data = null;
    }
  }

  get data(): GeometryDataUnion | null {
    return this._data;
  }

  set data(value: GeometryDataUnion | null) {
    this._data = value;
  }

  toFbsT(): FbsGeometryDataT {
    const t = new FbsGeometryDataT();
    if (this._data instanceof RawGeom) {
      t.dataType = FbsGeometryDataUnion.RawGeom;
      t.data = this._data.toFbsT();
    } else if (this._data instanceof NodeIdPair) {
      t.dataType = FbsGeometryDataUnion.NodeIdPair;
      t.data = this._data.toFbsT();
    }
    return t;
  }

  toBytes(): Uint8Array {
    const builder = new flatbuffers.Builder();
    const offset = this.toFbsT().pack(builder);
    builder.finishSizePrefixed(offset);
    return builder.asUint8Array();
  }
}

