export class UlFieldRelationship {
  private _relationshipData!: UlFieldRelationshipData | null;

  private _relationshipDisplayName!: string | null;

  constructor(arg?: FbsUlFieldRelationship | Uint8Array) {
    if (arg instanceof Uint8Array) {
      const buf = new flatbuffers.ByteBuffer(arg);
      const fbs = FbsUlFieldRelationship.getSizePrefixedRootAsUlFieldRelationship(buf);
      this._initFromFbs(fbs);
    } else if (arg instanceof FbsUlFieldRelationship) {
      this._initFromFbs(arg);
    } else {
      this._relationshipData = null;
      this._relationshipDisplayName = null;
    }
  }

  private _initFromFbs(fbs: FbsUlFieldRelationship): void {
    const relationshipDataTy = fbs.relationshipDataType();
    if (relationshipDataTy === FbsUlFieldRelationshipData.HierarchyRelationshipData) {
      const relationshipDataFbsVal = fbs.relationshipData(new FbsHierarchyRelationshipData());
      this._relationshipData = relationshipDataFbsVal ? new HierarchyRelationshipData(relationshipDataFbsVal) : null;
    } else if (relationshipDataTy === FbsUlFieldRelationshipData.CategoryRelationshipData) {
      const relationshipDataFbsVal = fbs.relationshipData(new FbsCategoryRelationshipData());
      this._relationshipData = relationshipDataFbsVal ? new CategoryRelationshipData(relationshipDataFbsVal) : null;
    } else if (relationshipDataTy === FbsUlFieldRelationshipData.NestedCategoryRelationshipData) {
      const relationshipDataFbsVal = fbs.relationshipData(new FbsNestedCategoryRelationshipData());
      this._relationshipData = relationshipDataFbsVal ? new NestedCategoryRelationshipData(relationshipDataFbsVal) : null;
    } else if (relationshipDataTy === FbsUlFieldRelationshipData.NestedHierarchyRelationshipData) {
      const relationshipDataFbsVal = fbs.relationshipData(new FbsNestedHierarchyRelationshipData());
      this._relationshipData = relationshipDataFbsVal ? new NestedHierarchyRelationshipData(relationshipDataFbsVal) : null;
    } else {
      this._relationshipData = null;
    }
    this._relationshipDisplayName = fbs.relationshipDisplayName();
  }

  get relationshipData(): UlFieldRelationshipData | null {
    return this._relationshipData;
  }

  set relationshipData(value: UlFieldRelationshipData | null) {
    this._relationshipData = value;
  }

  get relationshipDisplayName(): string | null {
    return this._relationshipDisplayName;
  }

  set relationshipDisplayName(value: string | null) {
    this._relationshipDisplayName = value;
  }

  toFbsT(): FbsUlFieldRelationshipT {
    const t = new FbsUlFieldRelationshipT();
    if (this._relationshipData instanceof HierarchyRelationshipData) {
      t.relationshipDataType = FbsUlFieldRelationshipData.HierarchyRelationshipData;
      t.relationshipData = this._relationshipData.toFbsT();
    } else if (this._relationshipData instanceof CategoryRelationshipData) {
      t.relationshipDataType = FbsUlFieldRelationshipData.CategoryRelationshipData;
      t.relationshipData = this._relationshipData.toFbsT();
    } else if (this._relationshipData instanceof NestedCategoryRelationshipData) {
      t.relationshipDataType = FbsUlFieldRelationshipData.NestedCategoryRelationshipData;
      t.relationshipData = this._relationshipData.toFbsT();
    } else if (this._relationshipData instanceof NestedHierarchyRelationshipData) {
      t.relationshipDataType = FbsUlFieldRelationshipData.NestedHierarchyRelationshipData;
      t.relationshipData = this._relationshipData.toFbsT();
    }
    t.relationshipDisplayName = this._relationshipDisplayName;
    return t;
  }

  toBytes(): Uint8Array {
    const builder = new flatbuffers.Builder();
    const offset = this.toFbsT().pack(builder);
    builder.finishSizePrefixed(offset);
    return builder.asUint8Array();
  }
}
